import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import Alert from './Alert';

describe('Alert', () => {
  it('should render', () => {
    render(<Alert message="Alert" type="info" />);
    expect(screen.getByText('Alert')).toBeInTheDocument();
    expect(screen.getByTestId('Info')).toBeInTheDocument();
  });

  it('should render with warning type', () => {
    render(<Alert message="Alert Warning" type="warning" />);
    expect(screen.getByText('Alert Warning')).toBeInTheDocument();
    expect(screen.getByTestId('AlertTriangle')).toBeInTheDocument();
  });

  it('should render with default type', () => {
    render(<Alert message="Alert" />);
    expect(screen.getByText('Alert')).toBeInTheDocument();
    expect(screen.getByTestId('Info')).toBeInTheDocument();
  });

  it('should render with error type', () => {
    render(<Alert message="Alert Error" type="error" />);

    expect(screen.getByText('Alert Error')).toBeInTheDocument();
    expect(screen.getByTestId('AlertOctagon')).toBeInTheDocument();
  });

  it('should render with success type', () => {
    render(<Alert message="Alert Success" type="success" />);

    expect(screen.getByText('Alert Success')).toBeInTheDocument();
    expect(screen.getByTestId('Checkmark2')).toBeInTheDocument();
  });

  it('should render with snackbar type', () => {
    render(<Alert message="Snackbar Error" componentVariant="snackbar" />);

    expect(screen.getByText('Snackbar Error')).toBeInTheDocument();
    expect(screen.queryByTestId('Info')).not.toBeInTheDocument();
  });

  it('should call the action function when clicked', () => {
    const action = jest.fn();
    render(
      <Alert
        message="Alert Error"
        type="error"
        actions={[{ name: 'Action', action: () => action() }]}
      />
    );

    fireEvent.click(screen.getByText('Action'));

    expect(action).toBeCalledTimes(1);
  });

  it('should call the action function when clicked', () => {
    const action1 = jest.fn();
    const action2 = jest.fn();
    render(
      <Alert
        message="Alert Error"
        type="error"
        actions={[
          { name: 'Action 1', action: () => action1() },
          { name: 'Action 2', action: () => action2() },
        ]}
      />
    );

    fireEvent.click(screen.getByText('Action 2'));

    expect(action2).toBeCalledTimes(1);
  });

  it('should call onClose function when clicked', () => {
    const onClose = jest.fn();
    render(<Alert message="Alert Error" type="error" onClose={onClose} showCloseButton />);

    fireEvent.click(screen.getByTestId('XCircle'));

    expect(onClose).toBeCalledTimes(1);
  });
});
